 AND src.terminal_receipt_id=tr.id AND tr.session_id=src.session_id AND tr.source_sha256=src.source_sha256 AND tr.outcome='success' AND tr.publication_id IS NOT NULL AND ar.state='completed' AND cardinality(ar.execution_auth_ids)=2 AND cardinality(ar.member_character_ids)=2
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 sp WHERE sp.release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-source-key/1','publication_request',ar.publication_request)) AND sp.created_by='postgres'::name AND sp.payload->>'schema_version'='human-custom-source/1' AND (CASE WHEN presentation_inherited THEN sp.payload_sha256='477b4631c0c8f1fb3db585edbdc12e32ee9420ffb9dd9f47234cad984a1679c1' AND src.session_id='9845891c-2e02-5ba6-8b45-68ff9f2fe268'::uuid AND tr.id='535535b1-340e-4472-a4a0-9d1914fc739f'::uuid AND ar.id='22765216-5f14-573f-86e4-60c402941ec9'::uuid ELSE (sp.payload->>'capability_sha256'=csha OR (sp.payload->>'capability_sha256' IS DISTINCT FROM csha AND (mission_factory_owner.human_staff_context_records_v1(observed,csha,ar.id,'continuity_historical',g) OR mission_factory_owner.human_staff_lease_valid_verified_v1(observed,ar.id,false,p_context)))) END) AND sp.payload->>'source_sha256'=ar.source_sha256 AND sp.payload->>'arc_id'=ar.id::text AND sp.payload_sha256=mission_factory_owner.sha(sp.payload))
